<script setup>
import { computed, onMounted, ref } from 'vue'
import { Save, ArrowLeft } from '@lucide/vue'
import { useRouter } from 'vue-router'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Card, CardContent } from '@/components/ui/card'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { getPeminjaman } from '@/services/peminjamanService'
import { getPengembalian, tambahPengembalian } from '@/services/pengembalianService'
const router = useRouter(), loans = ref([]), error = ref('')
const form = ref({ peminjaman_id: '', kondisi: '', tanggal_pengembalian: '', denda: 0 })
const pilihan = computed(() => loans.value.map(item => ({ ...item, label: `${item.nama_peminjam} - ${item.alat}` })))
onMounted(async () => { try { const [p, r] = await Promise.all([getPeminjaman(), getPengembalian()]); const done = new Set(r.data.map(item => item.peminjaman_id)); loans.value = p.data.filter(item => item.status === 'Disetujui' && !done.has(item.id)) } catch (e) { error.value = e.response?.data?.message || 'Gagal memuat data.' } })
async function submit() { try { await tambahPengembalian(form.value); router.push('/admin/pengembalian') } catch (e) { error.value = e.response?.data?.message || 'Gagal menyimpan pengembalian.' } }
</script>
<template><div class="py-20 px-20 pt-8"><Button @click="router.push('/admin/pengembalian')" variant="outline" class="gap-2"><ArrowLeft :size="16" />Kembali</Button><h1 class="text-3xl font-bold pt-3">Tambah Pengembalian Baru</h1><Card class="shadow-sm mt-3"><CardContent><form @submit.prevent="submit" class="grid grid-cols-1 md:grid-cols-2 gap-3 gap-x-10 pb-4 p-2"><div><label class="text-sm font-medium text-gray-800">Nama Peminjam <span class="text-[#DC2626]">*</span></label><Select v-model="form.peminjaman_id"><SelectTrigger class="!h-[40px] w-full"><SelectValue placeholder="Pilih peminjam" /></SelectTrigger><SelectContent><SelectItem v-for="item in pilihan" :key="item.id" :value="item.id">{{ item.label }}</SelectItem></SelectContent></Select></div><div><label class="text-sm font-medium text-gray-800">Kondisi <span class="text-[#DC2626]">*</span></label><Select v-model="form.kondisi"><SelectTrigger class="!h-[40px] w-full"><SelectValue placeholder="Pilih kondisi" /></SelectTrigger><SelectContent><SelectItem value="Baik">Baik</SelectItem><SelectItem value="Rusak Ringan">Rusak Ringan</SelectItem><SelectItem value="Rusak Berat">Rusak Berat</SelectItem></SelectContent></Select></div><div><label class="text-sm font-medium text-gray-800">Alat</label><Input :model-value="pilihan.find(item => item.id === form.peminjaman_id)?.alat || ''" type="text" placeholder="Pilih peminjam terlebih dahulu" class="h-10" disabled /></div><div><label class="text-sm font-medium text-gray-800">Tanggal Pengembalian <span class="text-[#DC2626]">*</span></label><Input v-model="form.tanggal_pengembalian" type="date" required class="h-10" /></div><div><label class="text-sm font-medium text-gray-800">Status</label><Input :model-value="Number(form.denda) > 0 ? 'Denda' : 'Selesai'" class="h-10" disabled /></div><div><label class="text-sm font-medium text-gray-800">Denda</label><Input v-model.number="form.denda" type="number" min="0" placeholder="Masukkan denda" class="h-10" /></div><p v-if="error" class="text-sm text-red-600 md:col-span-2">{{ error }}</p><div class="flex justify-end items-center py-3 md:col-span-2"><Button type="submit" :disabled="!form.peminjaman_id || !form.kondisi"><Save :size="20" /> Tambah Pengembalian</Button></div></form></CardContent></Card></div></template>
